#include <algorithm>
#include <signal.h>
#include <unistd.h>
#include <array>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <map>
#include <string>
#include <vector>
#include <stdexcept>
template<class T>std::vector<T> read(std::string f){std::ifstream s(f,std::ios::binary|std::ios::ate);auto n=s.tellg();if(n<0||n%sizeof(T))throw std::runtime_error("bad input bytes");std::vector<T>v(size_t(n)/sizeof(T));s.seekg(0);s.read((char*)v.data(),n);if(!s)throw std::runtime_error("short read");return v;}
struct Rule{unsigned bit,in,out;bool seen=false;uint64_t inside=0,outside=0;};
int main(int argc,char**argv){try{if(argc!=8)throw std::runtime_error("component_rows component_runs rules outrows outruns width height");auto rows=read<uint32_t>(argv[1]),runs=read<uint32_t>(argv[2]);uint32_t w=std::stoul(argv[6]),h=std::stoul(argv[7]);if(!w||!h||rows.size()!=size_t(h)+1||runs.size()%3||rows.front()!=0||rows.back()!=runs.size()/3)throw std::runtime_error("invalid component arrays");std::map<uint32_t,Rule> rules;std::ifstream r(argv[3]);uint32_t root,bit,in,out;while(r>>root>>bit>>in>>out){if(bit>128||in<17||in>22||out<17||out>22||!rules.emplace(root,Rule{bit,in,out}).second)throw std::runtime_error("invalid rule");}if(!r.eof()||rules.empty())throw std::runtime_error("missing rules");std::ofstream orows(argv[4],std::ios::binary),result(argv[5],std::ios::binary);if(!orows||!result)throw std::runtime_error("output open failure");std::vector<uint8_t>mask(w);std::array<uint64_t,23> counts={};uint32_t nr=0;orows.write((char*)&nr,4);for(uint32_t y=0;y<h;y++){if(rows[y]>rows[y+1])throw std::runtime_error("non-monotone offsets");if(!std::cin.read((char*)mask.data(),w))throw std::runtime_error("truncated region raster stream");uint32_t end=0,last=0,prev_end=0;bool has=false;auto emit=[&](uint32_t e,uint32_t c){if(e==end)return;if(has&&last==c){result.seekp(-8,std::ios::cur);result.write((char*)&e,4);result.write((char*)&c,4);}else{result.write((char*)&e,4);result.write((char*)&c,4);if(nr==UINT32_MAX)throw std::runtime_error("too many output runs");nr++;has=true;last=c;}if(c)counts[c]+=(uint64_t)e-end;end=e;};for(uint32_t i=rows[y];i<rows[y+1];i++){uint32_t a=runs[3*i],b=runs[3*i+1],id=runs[3*i+2];if(a<prev_end||a>=b||b>w)throw std::runtime_error("invalid component interval");prev_end=b;auto it=rules.find(id);if(it==rules.end())continue;auto &rule=it->second;rule.seen=true;emit(a,0);uint32_t x=a;while(x<b){auto value=[&](uint32_t z){return rule.bit?(mask[z]&rule.bit?rule.in:rule.out):rule.in;};uint32_t code=value(x),j=x+1;while(j<b&&value(j)==code)j++;if(!rule.bit||(mask[x]&rule.bit))rule.inside+=j-x;else rule.outside+=j-x;emit(j,code);x=j;}}emit(w,0);orows.write((char*)&nr,4);}if(!orows||!result)throw std::runtime_error("output write failure");for(auto&[id,rule]:rules)if(!rule.seen)throw std::runtime_error("selected root missing: "+std::to_string(id));for(auto&[id,rule]:rules)std::cerr<<"RULE "<<id<<" "<<rule.inside<<" "<<rule.outside<<"\n";for(int c=17;c<=22;c++)std::cerr<<"CODE "<<c<<" "<<counts[c]<<"\n";return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
